using P = pair<long long, int>;
vector<long long> dijkstra(int s, vector<vector<pair<int,int>>>& g) {
    vector<long long> d(g.size(), LLONG_MAX);
    priority_queue<P, vector<P>, greater<P>> pq;
    d[s] = 0; pq.push({0, s});
    while (!pq.empty()) {
        auto [du, u] = pq.top(); pq.pop();
        if (du > d[u]) continue;           // stale entry
        for (auto [v, w] : g[u])
            if (du + w < d[v]) {
                d[v] = du + w;
                pq.push({d[v], v});
            }
    }
    return d;
}
